From 9e8fe2c824d599bcfaca720ee623e90d5d99921a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:56:22 +0100
Subject: [PATCH] shell: keep handling notifications without a Notifications
 widget

Disabling the Notifications tray entry stopped all notifications, since
only the widget loaded their shared state. plasmashell now loads it too
and places popups on the primary screen, so drop the warning about it.

BUG: 485383
---
 applets/notifications/global/Globals.qml | 19 +++++++-------
 applets/systemtray/qml/ConfigGeneral.qml |  9 -------
 shell/shellcorona.cpp                    | 32 ++++++++++++++++++++++++
 shell/shellcorona.h                      |  2 ++
 4 files changed, 43 insertions(+), 19 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..089c5f5005 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -76,6 +76,9 @@ QtObject {
     // all notification plasmoids
     property var plasmoidItems: []

+    // Where to place popups when there is no notification plasmoid, set by the shell
+    property rect fallbackScreenRect: Qt.rect(0, 0, -1, -1)
+
     property int popupLocation: {
         // if we are on mobile, we can ignore the settings totally and just
         // align it to top center
@@ -126,7 +129,7 @@ QtObject {

     readonly property rect screenRect: {
         if (!plasmoid) {
-            return Qt.rect(0, 0, -1, -1);
+            return fallbackScreenRect;
         }

         const containment = plasmoid.containment;
@@ -319,22 +322,18 @@ QtObject {
     }

     function positionPopups() {
-        if (!plasmoid) {
-            return;
-        }
-
         const screenRect = globals.screenRect;
         if (screenRect.width <= 0 || screenRect.height <= 0) {
             return;
         }
-        if (!globals.visualParent) {
+        if (plasmoid && !globals.visualParent) {
             return;
         }

         let effectivePopupLocation = popupLocation;

         const visualParent = globals.visualParent;
-        const visualParentWindow = visualParent.Window.window;
+        const visualParentWindow = visualParent ? visualParent.Window.window : null;

         // When no horizontal alignment is specified, place it depending on which half of the *panel*
         // the notification plasmoid is in
@@ -352,7 +351,7 @@ QtObject {

         // When no vertical alignment is specified, place it depending on which half of the *screen*
         // the notification plasmoid is in
-        if (!(effectivePopupLocation & (Qt.AlignTop | Qt.AlignBottom))) {
+        if (visualParent && !(effectivePopupLocation & (Qt.AlignTop | Qt.AlignBottom))) {
             const screenVCenter = screenRect.y + screenRect.height / 2;
             const iconVCenter = visualParent.mapToGlobal(0, visualParent.height / 2).y;

@@ -427,7 +426,7 @@ QtObject {
     }

     property NotificationManager.Notifications popupNotificationsModel: NotificationManager.Notifications {
-        limit: plasmoid ? (Math.ceil(globals.screenRect.height / (Kirigami.Units.gridUnit * 4))) : 0
+        limit: Math.max(0, Math.ceil(globals.screenRect.height / (Kirigami.Units.gridUnit * 4)))
         showExpired: false
         showDismissed: false
         showAddedDuringInhibition: false
@@ -797,6 +796,6 @@ QtObject {

     property Notifications.GlobalShortcuts shortcuts: Notifications.GlobalShortcuts {
         onToggleDoNotDisturbTriggered: globals.toggleDoNotDisturbMode()
-        onClearHistoryTriggered: plasmoidItem.clearNotificationHistoryAndShowOsd()
+        onClearHistoryTriggered: plasmoidItem?.clearNotificationHistoryAndShowOsd()
     }
 }
diff --git a/applets/systemtray/qml/ConfigGeneral.qml b/applets/systemtray/qml/ConfigGeneral.qml
index 7895a1e414..7243258768 100644
--- a/applets/systemtray/qml/ConfigGeneral.qml
+++ b/applets/systemtray/qml/ConfigGeneral.qml
@@ -190,15 +190,6 @@ KCMUtils.ScrollViewKCM {
             text: xi18nc("@info:usagetip", "Disabling the clipboard is not recommended, as it will cause copied data to be lost when the application it was copied from is closed.<nl/><nl/>Only do this if you’ve manually added a standalone Clipboard widget somewhere else, or are using a 3rd-party clipboard manager. Also, instead consider configuring the clipboard to not save history, or to only remember one item at a time.")
         }

-        Kirigami.InlineMessage {
-            id: disablingNotificationsMessage
-
-            visible: iconsPage.changedVisibility.get("org.kde.plasma.notifications") === "disabled"
-            Layout.fillWidth: true
-            type: Kirigami.MessageType.Warning
-            text: xi18nc("@info:usagetip", "Disabling the Notifications widget is not recommended, as notifications sent by apps will no longer be shown.<nl/><nl/>Only do this if you’ve manually added a standalone Notifications widget somewhere else, or are intentionally using a 3rd-party notification manager to handle notifications.")
-        }
-
         Kirigami.FormLayout {
             id: formLayout

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..b96d460ce4 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -37,6 +37,7 @@
 #include <KLocalizedString>
 #include <KMessageBox>
 #include <KPackage/PackageLoader>
+#include <KPluginFactory>
 #include <KSycoca>
 #include <KWindowSystem>

@@ -861,6 +862,37 @@ void ShellCorona::load()
         KConfigGroup coronaConfig(config(), u"General"_s);
         setImmutability((Plasma::Types::ImmutabilityType)coronaConfig.readEntry("immutability", static_cast<int>(Plasma::Types::Mutable)));
     }
+
+    loadNotifications();
+}
+
+void ShellCorona::loadNotifications()
+{
+    // Notifications are received and shown by the Notifications widget's shared state,
+    // load it even without such a widget so that notifications keep working
+    if (m_notificationGlobals || m_shell != u"org.kde.plasma.desktop") {
+        return;
+    }
+
+    const KPluginMetaData metaData(u"plasma/applets/org.kde.plasma.notifications"_s);
+    if (!metaData.isValid() || !KPluginFactory::loadFactory(metaData)) {
+        qCWarning(PLASMASHELL) << "Could not load the notifications plugin";
+        return;
+    }
+
+    m_notificationGlobals = PlasmaQuick::globalEngine()->singletonInstance<QObject *>("plasma.applet.org.kde.plasma.notifications", "Globals");
+    if (!m_notificationGlobals) {
+        qCWarning(PLASMASHELL) << "Could not load the notifications";
+        return;
+    }
+
+    auto updateScreenRect = [this](int id) {
+        if (id == 0) {
+            m_notificationGlobals->setProperty("fallbackScreenRect", QRectF(availableScreenRect(0)));
+        }
+    };
+    connect(this, &Plasma::Corona::availableScreenRectChanged, m_notificationGlobals, updateScreenRect);
+    updateScreenRect(0);
 }

 #ifndef NDEBUG
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..0f6cd71bb9 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -288,6 +288,7 @@ private:
     void executeSetupPlasmoidScript(Plasma::Containment *containment, Plasma::Applet *applet);
     void checkAllDesktopsUiReady();
     void activateLauncherMenu(const QString &screenName);
+    void loadNotifications();

     void setupLookAndFeel();
     void handleColorRequestedFromDBus(const QDBusMessage &msg);
@@ -333,6 +334,7 @@ private:

     StrutManager *m_strutManager;
     QPointer<ShellContainmentConfig> m_shellContainmentConfig;
+    QPointer<QObject> m_notificationGlobals;
     // The set of all the screens which have both the desktop and all panels (if any) fully loaded
     QSet<uint> m_screensWithUiReady;
     friend class ShellTest;
